import{_ as t}from"./chunks/knowledge-base.Co7nYv_M.js";import{_ as s,o as n,c as a,ai as r}from"./chunks/framework.C33Uq6m-.js";const g=JSON.parse('{"title":"Base de Connaissances","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/knowledge-base.md","filePath":"fr/guide/knowledge-base.md"}'),o={name:"fr/guide/knowledge-base.md"};function i(d,e,l,c,u,m){return n(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="base-de-connaissances" tabindex="-1">Base de Connaissances <a class="header-anchor" href="#base-de-connaissances" aria-label="Permalink to &quot;Base de Connaissances&quot;">​</a></h1><p>La page Base de Connaissances implémente un pipeline RAG (Retrieval-Augmented Generation) complet et local. Téléversez vos documents, générez leurs embeddings et recherchez en langage naturel -- le tout stocké dans votre navigateur.</p><p><strong>Élément de la barre latérale :</strong> Base de Connaissances <strong>Route :</strong> <code>/rag</code></p><p><img src="'+t+'" alt="Interface Base de Connaissances"></p><h2 id="qu-est-ce-que-le-rag" tabindex="-1">Qu&#39;est-ce que le RAG ? <a class="header-anchor" href="#qu-est-ce-que-le-rag" aria-label="Permalink to &quot;Qu&#39;est-ce que le RAG ?&quot;">​</a></h2><p>RAG signifie <strong>Retrieval-Augmented Generation</strong> (Génération Augmentée par la Récupération). Au lieu de se fier uniquement à ce sur quoi un modèle a été entraîné, le RAG permet de lui fournir des extraits pertinents de vos propres documents. Le modèle utilise ensuite ces extraits comme contexte pour donner des réponses plus précises et ancrées dans vos données.</p><h2 id="televersement-de-documents" tabindex="-1">Téléversement de documents <a class="header-anchor" href="#televersement-de-documents" aria-label="Permalink to &quot;Téléversement de documents&quot;">​</a></h2><p>Cliquez sur <strong>Télécharger</strong> et sélectionnez un ou plusieurs fichiers. Formats pris en charge :</p><table tabindex="0"><thead><tr><th>Format</th><th>Extension</th><th>Analyseur</th></tr></thead><tbody><tr><td>PDF</td><td><code>.pdf</code></td><td>pdfjs-dist (chargé à la demande)</td></tr><tr><td>Word</td><td><code>.docx</code></td><td>mammoth</td></tr><tr><td>Texte brut</td><td><code>.txt</code>, <code>.md</code></td><td>Natif</td></tr><tr><td>CSV</td><td><code>.csv</code></td><td>papaparse</td></tr></tbody></table><h2 id="le-pipeline-d-ingestion" tabindex="-1">Le pipeline d&#39;ingestion <a class="header-anchor" href="#le-pipeline-d-ingestion" aria-label="Permalink to &quot;Le pipeline d&#39;ingestion&quot;">​</a></h2><p>Après le téléversement, chaque document passe par trois étapes :</p><ol><li><strong>Analyse</strong> -- Extraction du texte brut depuis le format de fichier</li><li><strong>Découpage</strong> -- Fractionnement du texte en segments chevauchants (taille et chevauchement configurables)</li><li><strong>Embedding</strong> -- Génération d&#39;un vecteur pour chaque segment à l&#39;aide du modèle d&#39;embedding choisi</li></ol><p>La progression est affichée par document. Une fois terminé, le statut du document passe à &quot;Prêt&quot;.</p><h2 id="recherche" tabindex="-1">Recherche <a class="header-anchor" href="#recherche" aria-label="Permalink to &quot;Recherche&quot;">​</a></h2><ol><li>Saisissez une requête en langage naturel dans la barre de recherche.</li><li>Les résultats apparaissent classés par <strong>similarité cosinus</strong> -- les segments les plus pertinents sémantiquement en premier.</li><li>Chaque résultat affiche : <ul><li>L&#39;extrait de texte correspondant</li><li>Le nom du document source</li><li>Le score de similarité</li><li>Les métadonnées (numéro de page, section, positions dans le texte)</li></ul></li></ol><h2 id="gestion-des-documents" tabindex="-1">Gestion des documents <a class="header-anchor" href="#gestion-des-documents" aria-label="Permalink to &quot;Gestion des documents&quot;">​</a></h2><ul><li><strong>Activer/Désactiver</strong> -- Basculez les documents pour la recherche. Les documents désactivés ne sont pas inclus dans les résultats.</li><li><strong>Supprimer</strong> -- Supprime un document et tous ses segments d&#39;IndexedDB.</li><li><strong>Indicateurs de statut</strong> -- Affiche l&#39;étape de traitement (analyse, découpage, embedding, prêt, erreur).</li></ul><h2 id="stockage" tabindex="-1">Stockage <a class="header-anchor" href="#stockage" aria-label="Permalink to &quot;Stockage&quot;">​</a></h2><p>Tout est stocké dans <strong>IndexedDB</strong>, la base de données intégrée de votre navigateur :</p><ul><li>Zéro coût -- aucun service externe nécessaire</li><li>Zéro configuration -- fonctionne immédiatement</li><li>Les données restent sur votre machine</li><li>Survit aux actualisations du navigateur (mais pas à l&#39;effacement des données du navigateur)</li></ul><h2 id="integration-avec-le-chat" tabindex="-1">Intégration avec le Chat <a class="header-anchor" href="#integration-avec-le-chat" aria-label="Permalink to &quot;Intégration avec le Chat&quot;">​</a></h2><p>Lorsque vous avez des documents dans la Base de Connaissances, les segments pertinents peuvent être automatiquement inclus comme contexte dans vos conversations de chat, ancrant les réponses du modèle dans vos données.</p><h2 id="astuces" tabindex="-1">Astuces <a class="header-anchor" href="#astuces" aria-label="Permalink to &quot;Astuces&quot;">​</a></h2><ul><li><strong>Des segments plus petits</strong> (200-400 tokens) tendent à produire des résultats de recherche plus précis.</li><li><strong>Le modèle d&#39;embedding compte</strong> -- <code>nomic-embed-text</code> fonctionne généralement bien pour les textes en anglais.</li><li>Les PDF volumineux prennent du temps à traiter. L&#39;interface affiche la progression pour que vous puissiez suivre le pipeline.</li><li>Vous pouvez télécharger plusieurs documents et effectuer des recherches sur l&#39;ensemble simultanément.</li></ul>',24)])])}const f=s(o,[["render",i]]);export{g as __pageData,f as default};
